Modify the search_users function to include an ownership check before returning results. For example:

@users_bp.route("/search", methods=["GET"])
@require_role("manager")
def search_users():
    name = request.args.get("name", "")
    session = get_session()
    user_id = g.user.id  # Assuming the current user's ID is available via g.user
    rows = session.execute(
        text(f"SELECT id, username, role FROM users WHERE username LIKE '%{name}%' AND (id = :user_id OR role = 'admin')")
    ).params(user_id=user_id)
    return jsonify([dict(r._mapping) for r in rows])
